; div_edges.asm - DIV/IDIV r8/r16/r32 edge cases against the 486's rules.
;
; Generated by scratch/make_div_edges_z486.py from the Zet98 reference at
; d4a3789 (tests/hardware/div_edges.asm + tests/make_div_edges.py): quotient
; range, truncation toward zero, remainder sign, and #DE on overflow or a zero
; divisor. The expected values are the Zet98 reference's transcription of the
; 486 DIV/IDIV rules -- NOT this core's RTL -- so a divergence is a finding.
;
; Each case sets the dividend and divisor, divides, and compares AX/DX (or
; EAX/EDX) and whether #DE fired with the expected values; the first mismatch
; reports its case number in EBP via DATA_PORT (0xE4). A #DE handler installed
; at IVT[0] records the fault and resumes at the per-case label, the same
; pattern the suite's seg_stack_wrap_rm uses for real-mode #SS/#GP.
;
; Cases 231 (IDIV r8 7F81h / 81h), 569 (r16 7FFF8001h / 8001h) and 927 (r32
; 7FFFFFFF80000001h / 80000001h) follow the silicon instead: the 486 divider
; completes each with the most negative quotient (see the cases).

BITS 16
org 0

STATUS_PORT equ 0xE0
DATA_PORT   equ 0xE4
STATUS_PASS equ 0x01
STATUS_FAIL equ 0xFF

start:
    cli
    cld
    mov ax, cs
    mov ds, ax
    xor ax, ax
    mov ss, ax
    mov sp, 0x8000

    ; IVT[0] = #DE (divide error) handler, in the code's own segment.
    mov es, ax
    mov word [es:0], de_handler
    mov word [es:2], cs

    jmp cases

; --- #DE: record the fault, restore a sane SP, resume at the case label ---
de_handler:
    inc word [cs:faulted]
    mov sp, 0x8000
    mov bx, [cs:resume_ip]
    jmp bx

fail:
    mov dx, DATA_PORT
    mov eax, ebp
    out dx, eax
    mov al, STATUS_FAIL
    mov dx, STATUS_PORT
    out dx, al
    hlt

cases:
; case 0: div r8 0x1 / 0x0 -> #DE
        mov     ebp, 0
        mov     word [resume_ip], .c0
        mov     word [faulted], 0
        mov     ax, 0x1
        mov     cl, 0x0
        div     cl
.c0:
        cmp     word [faulted], 1
        jne     fail
; case 1: div r8 0xffff / 0x0 -> #DE
